// tp3 kernel (see tp3.cu) and its per-config launcher, instantiated in csrc/inst/tp3_<id>*.cu (generated by
// configs.py, like conv_fused) so no TU compiles every config: all configs in one TU took 20 GB of cicc with
// the 7net-omni shapes.
#pragma once
#include <cuda_runtime.h>
#include <cstddef>
#include <type_traits>

#include "configs_gen.h"

namespace jet_mlip {
namespace tp3k {

enum Slot { OUT = 0, X = 1, W = 2, SH = 3 };

// Compile-time loop: f(std::integral_constant<int, I>) for I in [LO, HI). Binary
// split keeps template depth ~log2(N).
template <int LO, int HI, class F>
__device__ __forceinline__ void static_for(F&& f) {
  if constexpr (HI - LO == 1) {
    f(std::integral_constant<int, LO>{});
  } else if constexpr (HI - LO > 1) {
    constexpr int MID = LO + (HI - LO) / 2;
    static_for<LO, MID>(f);
    static_for<MID, HI>(f);
  }
}

// Lane-local layout (see config.h): per 32-channel chunk ch, lane u = 32*ch + lane owns
// x[off1 + u*(2l1+1) + m1] in register xv[xslot(b) + m1] (b = x block of the path) and
// out[off3 + u*(2l3+1) + m3] in gv[oslot(p) + m3]; W[wcol + u] in wv[p]. A path / block
// takes part in chunk ch only if 32*ch < mul; lanes >= ncol (mul 16) are idle.
template <typename T, class Cfg, int SLOT>
__global__ void __launch_bounds__(256) tp3_kernel(
    const T* __restrict__ x, const T* __restrict__ sh, const T* __restrict__ w,
    const T* __restrict__ g, const int* __restrict__ src, const int* __restrict__ dst,
    const int* __restrict__ rowptr, const int* __restrict__ perm, T* __restrict__ out, int n) {
  constexpr int NP = Cfg::NPATH, NS = Cfg::SH_DIM, NW = Cfg::NW;
  constexpr int NXB = nxb<Cfg>(), NX = xslot<Cfg>(NXB), NO = oslot<Cfg>(NP);
  const int wid = (blockIdx.x * blockDim.x + threadIdx.x) >> 5;  // edge, or dst node (OUT)
  const int lane = threadIdx.x & 31;
  if (wid >= n) return;
  int k0 = wid, k1 = wid + 1;  // OUT: this node's range in perm
  if constexpr (SLOT == OUT) { k0 = rowptr[wid]; k1 = rowptr[wid + 1]; }

  T sv[NS];
  if constexpr (SLOT == SH) static_for<0, NS>([&](auto i) { sv[i] = T(0); });

  static_for<0, nchmax<Cfg>()>([&](auto cc) {
    constexpr int ch = decltype(cc)::value;
    const int u = ch * 32 + lane;
    T xv[NX], wv[NP], gv[NO];
    static_for<0, NO>([&](auto i) { gv[i] = T(0); });
    for (int k = k0; k < k1; ++k) {  // one edge for X / W / SH, the node's edges for OUT
      const int e = SLOT == OUT ? perm[k] : k;
      const int s = src[e], d = SLOT == OUT ? wid : dst[e];
      if constexpr (SLOT != SH) static_for<0, NS>([&](auto i) { sv[i] = sh[(size_t)e * NS + i]; });
      const T* xr = x + (size_t)s * Cfg::IN_DIM;
      const T* gr = g + (size_t)d * Cfg::OUT_DIM;
      static_for<0, NXB>([&](auto bb) {
        constexpr int b = decltype(bb)::value, L = xb_l<Cfg>(b), NC = xb_ncol<Cfg>(b, ch);
        static_for<0, 2 * L + 1>([&](auto m) { xv[xslot<Cfg>(b) + m] = T(0); });
        if constexpr (NC > 0 && SLOT != X) {
          if (NC == 32 || lane < NC)
            static_for<0, 2 * L + 1>([&](auto m) { xv[xslot<Cfg>(b) + m] = xr[xb_off<Cfg>(b) + u * (2 * L + 1) + m]; });
        }
      });
      static_for<0, NP>([&](auto pp) {
        constexpr int p = decltype(pp)::value;
        constexpr PathT P = Cfg::paths[p];
        constexpr int L = P.l3, NC = cmin(32, P.mul - 32 * ch);
        wv[p] = T(0);
        if constexpr (NC > 0) {
          if (NC == 32 || lane < NC) {
            if constexpr (SLOT != OUT)
              static_for<0, 2 * L + 1>([&](auto m) { gv[oslot<Cfg>(p) + m] = gr[P.off3 + u * (2 * L + 1) + m]; });
            if constexpr (SLOT != W) wv[p] = w[(size_t)e * NW + P.wcol + u];
          }
        }
      });

      // the contraction; the SLOT operand is the accumulator
      static_for<0, Cfg::NFIBER>([&](auto f) {
        constexpr FiberT fb = Cfg::fibers[f];
        constexpr PathT pp = Cfg::paths[fb.p];
        if constexpr (pp.mul > 32 * ch) {
          constexpr int xi = xslot<Cfg>(xb_of<Cfg>(fb.p)) + fb.m1, si = pp.off2 + fb.m2, oi = oslot<Cfg>(fb.p) + fb.m3;
          constexpr T c = T(fb.coef);
          if constexpr (SLOT == OUT) gv[oi] += c * xv[xi] * sv[si] * wv[fb.p];
          else if constexpr (SLOT == X) xv[xi] += c * gv[oi] * sv[si] * wv[fb.p];
          else if constexpr (SLOT == W) wv[fb.p] += c * xv[xi] * sv[si] * gv[oi];
          else sv[si] += c * xv[xi] * wv[fb.p] * gv[oi];
        }
      });

      if constexpr (SLOT == W) {
        static_for<0, NP>([&](auto pp) {
          constexpr int p = decltype(pp)::value;
          constexpr PathT P = Cfg::paths[p];
          constexpr int NC = cmin(32, P.mul - 32 * ch);
          if constexpr (NC > 0) {
            if (NC == 32 || lane < NC) out[(size_t)e * NW + P.wcol + u] = wv[p];
          }
        });
      } else if constexpr (SLOT == X) {
        static_for<0, NXB>([&](auto bb) {
          constexpr int b = decltype(bb)::value, L = xb_l<Cfg>(b), NC = xb_ncol<Cfg>(b, ch);
          if constexpr (NC > 0) {
            if (NC == 32 || lane < NC) {
              T* o = out + (size_t)s * Cfg::IN_DIM + xb_off<Cfg>(b) + u * (2 * L + 1);
              static_for<0, 2 * L + 1>([&](auto m) { atomicAdd(o + m, xv[xslot<Cfg>(b) + m]); });
            }
          }
        });
      }
    }
    if constexpr (SLOT == OUT) {  // the node's row, this chunk's columns, written once
      static_for<0, NP>([&](auto pp) {
        constexpr int p = decltype(pp)::value;
        constexpr PathT P = Cfg::paths[p];
        constexpr int L = P.l3, NC = cmin(32, P.mul - 32 * ch);
        if constexpr (NC > 0) {
          if (NC == 32 || lane < NC) {
            T* o = out + (size_t)wid * Cfg::OUT_DIM + P.off3 + u * (2 * L + 1);
            static_for<0, 2 * L + 1>([&](auto m) { o[m] = gv[oslot<Cfg>(p) + m]; });
          }
        }
      });
    }
  });
  if constexpr (SLOT == SH) {
    static_for<0, NS>([&](auto i) {
      T v = sv[i];
#pragma unroll
      for (int off = 16; off > 0; off >>= 1) v += __shfl_xor_sync(0xffffffffu, v, off);
      if (lane == 0) out[(size_t)wid * NS + i] = v;
    });
  }
}

template <typename T, class Cfg, int SLOT>
void launch_cfg(const T* x, const T* sh, const T* w, const T* g, const int* src, const int* dst, const int* rowptr,
                const int* perm, T* out, int n, cudaStream_t stream) {
  tp3_kernel<T, Cfg, SLOT><<<(n * 32 + 255) / 256, 256, 0, stream>>>(x, sh, w, g, src, dst, rowptr, perm, out, n);
}

}  // namespace tp3k
}  // namespace jet_mlip
